<script lang="ts">
 import {zh} from './zh';
 import {untrack} from 'svelte';
 import {engine,type AriaEditorInfo} from '../../bridge/engine.svelte';
 import AriaSymbol from './AriaSymbol.svelte';
 let {kind,phone,whole=true,onclose,onedit}:{kind:string;phone:boolean;whole?:boolean;onclose:()=>void;onedit:(values:Record<string,unknown>)=>Promise<boolean>}=$props();
 let info=$state<AriaEditorInfo>({}),metadata=$state<Record<string,string>>({}),working=$state(false);
 let breakMode=$state('measures'),measures=$state(4),unit=$state('quarter'),bpm=$state('112'),tempoText=$state(''),typingTempo=$state(false),numberStarted=$state(false);
 let transposeMode=$state('interval'),down=$state(false),interval=$state(4),diatonic=$state(2),key=$state(0),minor=$state(false);
 let numerator=$state(4),denominator=$state(4),signatureStyle=$state('normal');
 let width=$state(innerWidth),height=$state(innerHeight);
 const landscape=$derived(phone&&width>height);
 const major=['C♭','G♭','D♭','A♭','E♭','B♭','F','C','G','D','A','E','B','F♯','C♯'];
 const relativeMinor=['A♭','E♭','B♭','F','C','G','D','A','E','B','F♯','C♯','G♯','D♯','A♯'];
 const intervals=[['Minor 2nd',3],['Major 2nd',4],['Minor 3rd',7],['Major 3rd',8],['Perfect 4th',11],['Aug. 4th',12],['Perfect 5th',14],['Minor 6th',17],['Major 6th',18],['Minor 7th',21],['Major 7th',22],['Dim. Octave',24],['Perfect Octave',25]] as const;
 const presets=[[4,4,'normal'],[4,4,'common'],[3,4,'normal'],[2,4,'normal'],[6,8,'normal'],[2,2,'cut'],[5,4,'normal'],[7,8,'normal'],[12,8,'normal']] as const;
 const glyphs:Record<string,string>={quarter:'𝅘𝅥',eighth:'𝅘𝅥𝅮',half:'𝅗𝅥',dottedQuarter:'𝅘𝅥.'};
 const nominal=$derived((info.nominalNumerator||4)/(info.nominalDenominator||4));
 const validPickup=$derived(numerator>0&&numerator/denominator<nominal);
 const validTempo=$derived(/^\d+$/.test(bpm)&&Number(bpm)>=20&&Number(bpm)<=300);
 const title=$derived(({addMeasures:'添加小节',setup:'Score Setup',autoBreaks:'Auto Breaks',tempo:'Tempo',transpose:'Transpose Score',pickup:'Pickup Measure',key:'Change Key Signature',time:'Change Time Signature'} as Record<string,string>)[kind]);
 $effect(()=>{const k=kind;untrack(()=>{
  info=engine.composerState({editorInfo:true})?.editorInfo||{};metadata={...info.metadata};key=info.key||0;
  if(k==='time'){numerator=info.currentNumerator||4;denominator=info.currentDenominator||4;}
  if(k==='pickup'){numerator=info.hasPickup?(info.pickupNumerator||1):1;denominator=info.hasPickup?(info.pickupDenominator||4):(info.nominalDenominator||4);}
 });});
 async function apply(values:Record<string,unknown>){working=true;try{if(await onedit(values))onclose();}finally{working=false;}}
 function digit(value:string){typingTempo=false;bpm=numberStarted?(bpm+value).slice(0,3):value;numberStarted=true;}
 function setSignature(n:number,d:number,s='normal'){numerator=n;denominator=d;signatureStyle=s;}
</script>
<svelte:window bind:innerWidth={width} bind:innerHeight={height}/>
{#if ['setup','autoBreaks','tempo','addMeasures'].includes(kind)}
 <div class="aria-form-header"><button disabled={working} onclick={onclose}>取消</button><strong>{zh(title)}</strong><button disabled={working||(kind==='tempo'&&!validTempo)} onclick={()=>apply(kind==='addMeasures'?{op:'addMeasures',count:measures}:kind==='setup'?{op:'metadata',metadata}:kind==='autoBreaks'?{op:'autoBreaks',mode:breakMode,count:measures}:{op:'tempo',unit,bpm:Number(bpm),text:tempoText})}>{zh(working?'Saving…':kind==='setup'?'Save':kind==='tempo'?'Done':kind==='addMeasures'?'Add':'Apply')}</button></div>
{/if}
{#if kind==='addMeasures'}
 <div class="measure-count"><strong>小节数</strong><div><button aria-label="减少小节" disabled={measures<=1} onclick={()=>measures--}>−</button><span>{measures}</span><button aria-label="增加小节" disabled={measures>=64} onclick={()=>measures++}>＋</button></div></div>
{:else if kind==='setup'}
 <div class="aria-form-body"><fieldset><legend>乐谱</legend><div class="form-section">{#each [['workTitle','Title'],['composer','Composer'],['subtitle','Subtitle'],['lyricist','Lyricist'],['arranger','Arranger']] as [tag,label]}<label class="form-row metadata"><input aria-label={zh(label)} placeholder={zh(label)} bind:value={metadata[tag]}/></label>{/each}</div></fieldset><fieldset><legend>初始设置</legend><div class="form-section"><p class="form-row"><AriaSymbol name="music.note.list"/>乐器与分谱沿用当前乐谱结构。</p><p class="form-row"><AriaSymbol name="slider.horizontal.3"/>初始调号、拍号和速度可在“更多”中设置。</p></div></fieldset></div>
{:else if kind==='autoBreaks'}
 <div class="aria-form-body"><fieldset><legend>自动换行</legend><div class="form-section"><label class="form-row">方式<select bind:value={breakMode}><option value="measures">每行小节数</option><option value="lock">固定当前排版</option><option value="remove">移除已有换行</option></select></label>{#if breakMode==='measures'}<label class="form-row">每行小节数<input aria-label="每行小节数" type="number" min="1" max="32" bind:value={measures}/></label><div class="form-row"><span>每行 {measures} 小节</span><div class="stepper"><button disabled={measures<=1} onclick={()=>measures--}>−</button><button disabled={measures>=32} onclick={()=>measures++}>＋</button></div></div>{/if}</div></fieldset></div><div class="break-footer"><button disabled={working} onclick={()=>apply({op:'autoBreaks',mode:'remove'})}>移除已有换行</button></div>
{:else if kind==='tempo'}
 <div class="tempo-body"><div class="tempo-preview"><span class="music">{glyphs[unit]}</span><b>=</b><strong aria-label="每分钟拍数">{bpm||'—'}</strong></div><label class="tempo-text"><input aria-label="速度说明" placeholder="例如：快板" bind:value={tempoText} onfocus={()=>typingTempo=true}/>{#if tempoText}<button aria-label="清除速度说明" onclick={()=>tempoText=''}><AriaSymbol name="xmark.circle.fill"/></button>{/if}</label><small>速度说明（可选）</small><div class="beat-label"><strong>拍单位</strong><small>以该音符时值为一拍。</small></div><div class="beat-units">{#each ['quarter','eighth','half','dottedQuarter'] as value}<button class:chosen={unit===value} aria-label={zh(value==='dottedQuarter'?'Dotted quarter note':value+' note')} onclick={()=>{unit=value;typingTempo=false;}}><span class="music">{glyphs[value]}</span></button>{/each}</div>{#if !typingTempo}<div class="number-pad">{#each ['1','2','3','4','5','6','7','8','9','=','0','erase'] as value}<button aria-label={zh(value==='erase'?'Erase tempo digit':value)} onclick={()=>{if(value==='erase'){bpm=bpm.slice(0,-1);numberStarted=true;}else if(value==='=')numberStarted=false;else digit(value);}}>{#if value==='erase'}<AriaSymbol name="delete.left" size={24}/>{:else}{value}{/if}</button>{/each}</div>{#if numberStarted&&!validTempo}<small>请输入 20～300 之间的每分钟拍数。</small>{/if}{/if}</div>
{:else if kind==='transpose'}
 <div class="transpose-panel"><h2>{zh(title)}</h2><div class="segmented">{#each [['interval','Interval'],['diatonic','Diatonic'],['key','To Key']] as [value,label]}<button class:chosen={transposeMode===value} onclick={()=>transposeMode=value}>{zh(label)}</button>{/each}</div><small>{zh(transposeMode==='key'?'Target key':transposeMode==='diatonic'?'Diatonic steps':'Interval')}</small><div class="transpose-options" class:list={transposeMode!=='interval'}>{#if transposeMode==='interval'}{#each intervals as [label,value]}<button class:chosen={interval===value} onclick={()=>interval=value}>{zh(label)}</button>{/each}{:else if transposeMode==='diatonic'}{#each ['2nd','3rd','4th','5th','6th','7th','Octave'] as label,index}<button class:chosen={diatonic===(index===6?25:index+1)} onclick={()=>diatonic=index===6?25:index+1}>{zh(label)}</button>{/each}{:else}{#each major as label,index}<button class:chosen={key===index-7} onclick={()=>key=index-7}>{zh(label)} major</button>{/each}{/if}</div><small>方向</small><div class="segmented"><button class:chosen={!down} onclick={()=>down=false}>向上</button><button class:chosen={down} onclick={()=>down=true}>向下</button></div><div class="panel-footer"><button onclick={onclose}>取消</button><button class="primary" disabled={working} onclick={()=>apply({op:'transpose',mode:transposeMode,interval:transposeMode==='diatonic'?diatonic:interval,key,down,whole})}>应用</button></div></div>
{:else if ['key','time','pickup'].includes(kind)}
 <div class="signature-editor" class:landscape><header><h2>{zh(title)}</h2><button aria-label="关闭" onclick={onclose}><AriaSymbol name="xmark" size={18}/></button></header><div class="summary"><div><small>当前</small><strong>{kind==='key'?major[(info.key||0)+7]+' 大调':kind==='pickup'?(info.hasPickup?info.pickupNumerator+'/'+info.pickupDenominator:info.nominalNumerator+'/'+info.nominalDenominator):info.currentNumerator+'/'+info.currentDenominator}</strong></div><span></span><div><small>修改后</small><strong>{kind==='key'?(minor?relativeMinor:major)[key+7]+(minor?' 小调':' 大调'):numerator+'/'+denominator}</strong></div></div>
  {#if kind==='key'}<div class="key-type"><strong>调式</strong><div class="segmented"><button class:chosen={!minor} onclick={()=>minor=false}>大调</button><button class:chosen={minor} onclick={()=>minor=true}>小调</button></div></div><div class="key-choices">{#each [['Sharps',[0,1,2,3,4,5,6,7]],['Flats',[-1,-2,-3,-4,-5,-6,-7]]] as group}<section><small>{zh(String(group[0]))}</small><div class="key-grid">{#each group[1] as k}<button class:chosen={key===Number(k)} onclick={()=>key=Number(k)}>{(minor?relativeMinor:major)[Number(k)+7]}{#if key===Number(k)}<span>✓</span>{/if}</button>{/each}</div></section>{/each}</div><div class="key-preview" aria-label="调号预览"><svg viewBox="0 0 320 88" aria-hidden="true">{#each [24,34,44,54,64] as y}<path d={'M12 '+y+'H308'} stroke="currentColor" stroke-width=".6"/>{/each}<text x="22" y="62" class="music" font-size="65">𝄞</text>{#each Array.from({length:Math.abs(key)},(_,i)=>i) as n}<text x={78+n*20} y={key>0?[33,48,28,43,58,38,53][n]:[48,33,53,38,58,43,63][n]} class="music" font-size="31">{key>0?'♯':'♭'}</text>{/each}</svg></div>
  {:else}<div class="signature-columns"><section><h3>常用</h3><div class="preset-grid">{#if kind==='time'}{#each presets as [n,d,s]}<button class:chosen={numerator===n&&denominator===d&&signatureStyle===s} onclick={()=>setSignature(n,d,s)}>{s==='common'?'C':s==='cut'?'₵':n+'/'+d}</button>{/each}{:else}{#each [[1,4],[1,8],[1,2],[3,8],[3,4],[1,16]].filter(([n,d])=>n/d<nominal) as [n,d]}<button class:chosen={numerator===n&&denominator===d} onclick={()=>setSignature(n,d)}>{n}/{d}</button>{/each}{/if}</div></section><section><h3>自定义</h3><div class="custom-controls"><label>{zh(kind==='pickup'?'Beats in pickup':'Beats per measure')}<div class="stepper"><button aria-label="减少拍数" disabled={numerator<=1} onclick={()=>{numerator--;signatureStyle='normal';}}>−</button><b>{numerator}</b><button aria-label="增加拍数" disabled={numerator>=32} onclick={()=>{numerator++;signatureStyle='normal';}}>＋</button></div></label><label>分母音符<select aria-label="分母音符" bind:value={denominator} onchange={()=>signatureStyle='normal'}>{#each [1,2,4,8,16] as d}<option value={d}>{d}</option>{/each}</select></label></div><p>{numerator} × 1/{denominator}{kind==='pickup'?' 弱起':'／小节'}</p>{#if kind==='pickup'&&info.hasPickup}<button class="remove-pickup" disabled={working} onclick={()=>apply({op:'pickup',remove:true})}>移除弱起</button>{/if}</section></div>{/if}
 </div><div class="signature-footer"><button onclick={onclose}>取消</button><button class="primary" disabled={working||(kind==='pickup'&&!validPickup)} onclick={()=>apply(kind==='key'?{op:'key',key}:{op:kind,numerator,denominator,style:signatureStyle})}>{zh(kind==='pickup'?(info.hasPickup?'Change':'Add'):'Change')}</button></div>
{/if}
