ay:flex;gap:16px;}.panel-footer button{flex:1;min-height:42px;border:0;border-radius:8px;background:var(--aria-fill);font-size:15px;font-weight:600;}.primary{background:var(--aria-active)!important;color:var(--aria-on-active)!important;}.signature-editor{padding:20px 24px 24px;display:grid;gap:20px;}.signature-editor header{position:relative;display:flex;align-items:center;justify-content:center;min-height:36px;}.signature-editor h2{font-size:20px;text-align:center;}.signature-editor header button{position:absolute;right:0;width:36px;height:36px;display:grid;place-items:center;background:none;border:0;}.summary{display:flex;align-items:center;justify-content:space-between;padding:18px 0;background:var(--aria-surface);border:1px solid var(--aria-line);border-radius:12px;}.summary>div{flex:1;display:grid;text-align:center;gap:4px;}.summary small{font-size:14px;color:var(--aria-muted);}.summary strong{font-size:21px;}.summary>span{height:48px;width:1px;background:var(--aria-line);}.key-type{display:flex;align-items:center;gap:18px;}.key-type>strong{width:94px;font-size:15px;}.key-type .segmented{flex:1;}.key-choices{display:grid;gap:16px;}.key-choices section+section{border-top:1px solid var(--aria-line);padding-top:16px;}.key-choices small{font-size:15px;color:var(--aria-muted);}.key-grid{display:flex;flex-wrap:wrap;gap:12px 16px;margin-top:10px;}.key-grid button{position:relative;width:48px;height:48px;border:1px solid var(--aria-line);border-radius:50%;background:var(--aria-surface);font-size:16px;font-weight:600;}.key-grid button.chosen{background:color-mix(in srgb, var(--aria-active) 12%, transparent);border-color:var(--aria-active);color:var(--aria-active);}.key-grid button span{position:absolute;right:-4px;top:-4px;width:20px;height:20px;border-radius:50%;background:var(--aria-active);color:var(--aria-on-active);display:grid;place-items:center;font-size:10px;}.key-preview{background:var(--aria-surface);border:1px solid var(--aria-line);border-radius:12px;}.key-p